static void ppu_resume(void)
{
	u32 reg_val, i;

	for (i = 0; i < 11; i++) {
		reg_val = readl(PCK600_REG_BASE + 0x1000 * i);
		reg_val |= 0x8;
		writel(reg_val, PCK600_REG_BASE + 0x1000 * i);

		/* do not care ppu gpu core status */
		if (i == 6)
			continue;

		while (!(readl(PCK600_REG_BASE + 0x1000 * i + 0x8) & 0x8))
			;
	}

